// Auto-generated FSM wrapper for hopfield_lut
// Async-cyclic update: neurons 0..15 in sequence

module hopfield_top #(
    parameter int N = 16
) (
    input  logic             clk,
    input  logic             rst_n,
    input  logic             load,      // 1: load i_state, 0: run
    input  logic [N-1:0]     i_state,   // initial/probe state
    output logic [N-1:0]     o_state,   // current state
    output logic             o_done     // high when fixed point reached
);

    logic [N-1:0] s, s_next_all;
    logic [$clog2(N)-1:0] neuron_idx;
    logic changed;

    // Combinational LUT block
    hopfield_lut #(.N(N)) lut_inst (.s(s), .s_next(s_next_all));

    assign o_state = s;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s          <= '0;
            neuron_idx <= '0;
            changed    <= 1'b0;
            o_done     <= 1'b0;
        end else if (load) begin
            s          <= i_state;
            neuron_idx <= '0;
            changed    <= 1'b0;
            o_done     <= 1'b0;
        end else if (!o_done) begin
            // Apply update for current neuron
            s[neuron_idx] <= s_next_all[neuron_idx];
            changed <= changed | (s_next_all[neuron_idx] != s[neuron_idx]);

            if (neuron_idx == N-1) begin
                // End of sweep
                if (!changed && !(s_next_all[neuron_idx] != s[neuron_idx]))
                    o_done <= 1'b1;  // no neuron changed → fixed point
                neuron_idx <= '0;
                changed    <= 1'b0;
            end else begin
                neuron_idx <= neuron_idx + 1;
            end
        end
    end

endmodule  // hopfield_top
